</code></pre> src/main.cpp<pre><code>#include &lt;Arduino.h&gt;
#include &lt;BLEDevice.h&gt;
#include &lt;BLEServer.h&gt;
#include &lt;BLE2902.h&gt;

const int LED_PIN = 13;

// UUID は https://www.uuidgenerator.net/ などで作れる
#define SERVICE_UUID "4fafc201-1fb5-459e-8fcc-c5c9c331914b"
#define LED_UUID     "beb5483e-36e1-4688-b7f5-ea07361b26a8"
#define COUNT_UUID   "1c95d5e3-d8f7-413a-bf3d-7a2e5d7be87e"

BLECharacteristic *countCharacteristic;
bool connected = false;
int count = 0;

// 接続・切断されたときに呼ばれる
class ServerCallbacks : public BLEServerCallbacks {
  void onConnect(BLEServer *server) override {
    connected = true;
    Serial.println("connected");
  }
  void onDisconnect(BLEServer *server) override {
    connected = false;
    Serial.println("disconnected");
    BLEDevice::startAdvertising();  // 再び接続を受け付ける
  }
};

// LED のキャラクタリスティックに書き込まれたときに呼ばれる
class LedCallbacks : public BLECharacteristicCallbacks {
  void onWrite(BLECharacteristic *characteristic) override {
    std::string value = characteristic-&gt;getValue();
    if (value.length() &gt; 0) {
      bool on = (value[0] != 0);  // 0 以外なら点灯
      digitalWrite(LED_PIN, on ? HIGH : LOW);
      Serial.println(on ? "LED ON" : "LED OFF");
    }
  }
};

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);

  BLEDevice::init("ESP32-yourname");  // スマホに表示される名前
  BLEServer *server = BLEDevice::createServer();
  server-&gt;setCallbacks(new ServerCallbacks());

  BLEService *service = server-&gt;createService(SERVICE_UUID);

  // LED：スマホから書き込める
  BLECharacteristic *ledCharacteristic = service-&gt;createCharacteristic(
      LED_UUID, BLECharacteristic::PROPERTY_WRITE);
  ledCharacteristic-&gt;setCallbacks(new LedCallbacks());

  // カウンター：スマホから読める・通知できる
  countCharacteristic = service-&gt;createCharacteristic(
      COUNT_UUID, BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_NOTIFY);
  countCharacteristic-&gt;addDescriptor(new BLE2902());  // 通知に必要な設定

  service-&gt;start();

  BLEAdvertising *advertising = BLEDevice::getAdvertising();
  advertising-&gt;addServiceUUID(SERVICE_UUID);
  BLEDevice::startAdvertising();  // 周囲に存在を知らせる
  Serial.println("waiting for connection...");
}

void loop() {
  if (connected) {
    countCharacteristic-&gt;setValue(count);  // 値を更新する
    countCharacteristic-&gt;notify();         // スマホに通知する
    count++;
  }
  delay(1000);
}
</code></pre>

src/main.cpp<pre><code>#include &lt;Arduino.h&gt;

const int AIN1 = 25;
const int AIN2 = 26;
const int PWMA = 27;
const int POT_PIN = 32;

// speed：-255（逆転・最大）〜 0（停止）〜 255（正転・最大）
void setMotor(int speed) {
  if (speed &gt; 0) {
    digitalWrite(AIN1, HIGH);
    digitalWrite(AIN2, LOW);
  } else if (speed &lt; 0) {
    digitalWrite(AIN1, LOW);
    digitalWrite(AIN2, HIGH);
  } else {
    digitalWrite(AIN1, LOW);
    digitalWrite(AIN2, LOW);
  }
  analogWrite(PWMA, abs(speed));  // 速さは PWM のデューティ比で決める
}

void setup() {
  Serial.begin(115200);
  pinMode(AIN1, OUTPUT);
  pinMode(AIN2, OUTPUT);
  pinMode(PWMA, OUTPUT);
}

void loop() {
  int raw = analogRead(POT_PIN);
  int speed = map(raw, 0, 4095, -255, 255);  // つまみの中央で停止

  // 中央付近は停止にする（つまみを中央にしても完全に 0 にはならないため）
  if (abs(speed) &lt; 30) {
    speed = 0;
  }

  setMotor(speed);
  Serial.printf("speed = %d\n", speed);
  delay(50);
}
</code></pre> <p><code>setMotor()</code> のように、よく使う処理を関数にまとめておくと、プログラムが読みやすくなります。2 輪の車を作る場合は、左右のモーターそれぞれに <code>setMotor</code> を用意し、左右の速さの差で曲がるように制御します。</p> <p>モーターを遅くすると回らない</p> <p>PWM のデューティ比を小さくしていくと、ある値より下ではモーターが回らなくなります。モーターやギアの摩擦に打ち勝つだけの力が出ないためです。 また、モーターの個体差で、同じデューティ比でも回転の速さが少しずつ違います。2 輪の車がまっすぐ走らないのは、このためです。</p> <p>逆起電力とノイズ</p> <p>モーターは、回転すると発電機としても働き、電源と逆向きの電圧（逆起電力）を発生させます。また、内部のブラシが擦れるときに電気的なノイズも出します。 ESP32 とモーターの電源を分けているのは、このノイズで ESP32 が誤動作するのを防ぐためでもあります。モーターの端子に 0.1 µF のコンデンサをはんだ付けすると、ノイズを減らせます。</p>

sender/src/main.cpp<pre><code>#include &lt;Arduino.h&gt;
#include &lt;WiFi.h&gt;
#include &lt;esp_now.h&gt;

const int BUTTON_PIN = 4;
const uint8_t GROUP = 1;  // ペアの相手と同じ番号にする

struct Message {
  uint8_t group;
  bool ledOn;
};

// FF:FF:FF:FF:FF:FF はブロードキャスト（全員宛て）のアドレス
uint8_t broadcastAddress[] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF};

bool lastState = HIGH;
bool ledOn = false;

void setup() {
  Serial.begin(115200);
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  WiFi.mode(WIFI_STA);  // ESP-NOW を使うには Wi-Fi を有効にする必要がある
  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW init failed");
    return;
  }

  // 送信先を登録する
  esp_now_peer_info_t peer = {};
  memcpy(peer.peer_addr, broadcastAddress, 6);
  peer.channel = 0;
  peer.encrypt = false;
  esp_now_add_peer(&amp;peer);
}

void loop() {
  bool state = digitalRead(BUTTON_PIN);

  if (lastState == HIGH &amp;&amp; state == LOW) {
    ledOn = !ledOn;

    Message message;
    message.group = GROUP;
    message.ledOn = ledOn;
    esp_now_send(broadcastAddress, (uint8_t *)&amp;message, sizeof(message));

    Serial.println(ledOn ? "send: ON" : "send: OFF");
    delay(50);  // チャタリング対策
  }

  lastState = state;
}
</code></pre>

receiver/src/main.cpp<pre><code>#include &lt;Arduino.h&gt;
#include &lt;WiFi.h&gt;
#include &lt;esp_now.h&gt;

const int LED_PIN = 13;
const uint8_t GROUP = 1;  // 送信側と同じ番号にする

struct Message {
  uint8_t group;
  bool ledOn;
};

// データを受信したときに呼ばれる
void onReceive(const uint8_t *mac, const uint8_t *data, int length) {
  if (length != sizeof(Message)) {
    return;  // 大きさが違うデータは無視する
  }

  Message message;
  memcpy(&amp;message, data, sizeof(message));

  if (message.group != GROUP) {
    return;  // ほかのグループのデータは無視する
  }

  digitalWrite(LED_PIN, message.ledOn ? HIGH : LOW);
  Serial.printf("receive from %02X:%02X:%02X:%02X:%02X:%02X: %s\n",
                mac[0], mac[1], mac[2], mac[3], mac[4], mac[5],
                message.ledOn ? "ON" : "OFF");
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);

  WiFi.mode(WIFI_STA);
  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW init failed");
    return;
  }

  esp_now_register_recv_cb(onReceive);  // 受信したときに呼ぶ関数を登録する
}

void loop() {
  // 受信は onReceive で行うので、ここでは何もしない
}
</code></pre> <p>受信側では、データが届くたびに <code>onReceive()</code> が自動で呼ばれます。このように、何かが起きたときに呼ばれるよう登録しておく関数を コールバック関数 と言います。</p> <p>MAC アドレス</p> <p>ネットワークにつながる機器それぞれに割り振られた、世界で 1 つの番号です（<code>24:6F:28:AB:CD:EF</code> のような形）。 ブロードキャストではなく特定の相手だけに送りたい場合は、相手の MAC アドレスを <code>broadcastAddress</code> の代わりに指定します。ESP32 の MAC アドレスは <code>WiFi.macAddress()</code> で調べられます。</p> <p>Arduino core のバージョンによる違い</p> <p>ESP-NOW の受信のコールバック関数の引数は、Arduino core のバージョン 3 以降で変わっています。インターネットで調べたサンプルがビルドできない場合は、どのバージョン向けのコードかを確認してください。この講座のコードは、<code>platformio.ini</code> で指定しているバージョン（Arduino core 2 系）向けです。</p>

