</code></pre> src/main.cpp<pre><code>#include &lt;Arduino.h&gt;
#include &lt;Wire.h&gt;
#include &lt;Adafruit_GFX.h&gt;
#include &lt;Adafruit_SSD1306.h&gt;

const int POT_PIN = 32;
const int SCREEN_WIDTH = 128;
const int SCREEN_HEIGHT = 64;

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &amp;Wire, -1);

void setup() {
  Serial.begin(115200);

  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {  // 0x3C は OLED の I2C アドレス
    Serial.println("SSD1306 not found");
    while (true) {
      delay(1000);
    }
  }
}

void loop() {
  int raw = analogRead(POT_PIN);
  int barWidth = map(raw, 0, 4095, 0, SCREEN_WIDTH);

  display.clearDisplay();  // 画面を消す（内部のバッファを消すだけで、まだ表示は変わらない）

  // 文字を表示する
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("Potentiometer");

  display.setTextSize(2);  // 2 倍の大きさ
  display.setCursor(0, 16);
  display.println(raw);

  // バーグラフを描く
  display.drawRect(0, 44, SCREEN_WIDTH, 16, SSD1306_WHITE);  // 枠
  display.fillRect(0, 44, barWidth, 16, SSD1306_WHITE);      // 中身

  display.display();  // バッファの内容を画面に送る
  delay(50);
}
</code></pre> <ul> <li>画面の座標は、左上が (0, 0) で、右に行くほど x が、下に行くほど y が大きくなります</li> <li>描画の関数は、ESP32 の中のメモリ（バッファ）に絵を描くだけです。<code>display.display()</code> を呼んだときに、まとめて画面に送られます</li> </ul> 関数 動作 <code>setCursor(x, y)</code> 文字を書き始める位置を決める <code>setTextSize(n)</code> 文字の大きさを n 倍にする <code>drawLine(x0, y0, x1, y1, 色)</code> 線を描く <code>drawRect(x, y, 幅, 高さ, 色)</code> 四角形の枠を描く <code>fillRect(x, y, 幅, 高さ, 色)</code> 塗りつぶした四角形を描く <code>drawCircle(x, y, 半径, 色)</code> 円を描く <p>OLED</p> <p>Organic Light Emitting Diode（有機 EL）の略です。液晶と違ってバックライトがなく、画素そのものが光るので、黒がはっきり表示され、消費電力も小さいのが特徴です。スマホの画面にも使われています。</p> <p>日本語の表示</p> <p>このライブラリで表示できるのは、英数字と一部の記号だけです。日本語を表示したい場合は、日本語フォントを含むライブラリ（U8g2 など）を使うか、文字を画像として用意して表示します。</p>

