    body { font-family: sans-serif; text-align: center; }
    a { display: inline-block; margin: 8px; padding: 16px 32px;
        color: white; background: #c62828; border-radius: 8px; text-decoration: none; }
  &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
  &lt;h1&gt;ESP32 LED&lt;/h1&gt;
)rawliteral";
  html += "&lt;p&gt;LED: ";
  html += ledOn ? "ON" : "OFF";
  html += "&lt;/p&gt;";
  html += R"rawliteral(
  &lt;a href="/on"&gt;ON&lt;/a&gt;
  &lt;a href="/off"&gt;OFF&lt;/a&gt;
&lt;/body&gt;
&lt;/html&gt;
)rawliteral";
  return html;
}

void handleRoot() {
  server.send(200, "text/html", makePage());
}

void handleOn() {
  ledOn = true;
  digitalWrite(LED_PIN, HIGH);
  server.sendHeader("Location", "/");  // トップページに戻す
  server.send(303);
}

void handleOff() {
  ledOn = false;
  digitalWrite(LED_PIN, LOW);
  server.sendHeader("Location", "/");
  server.send(303);
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);

  WiFi.softAP(SSID, PASSWORD);  // AP モードで Wi-Fi を始める
  Serial.print("IP address: ");
  Serial.println(WiFi.softAPIP());  // 通常は 192.168.4.1

  // URL ごとに、呼び出す関数を登録する
  server.on("/", handleRoot);
  server.on("/on", handleOn);
  server.on("/off", handleOff);
  server.begin();
}

void loop() {
  server.handleClient();  // ブラウザからのリクエストを処理する
}
